  let out = R(98, 234, 150, 6, '#7A4E63') + R(98, 234, 150, 1, '#A86B85') + R(98, 239, 150, 1, '#A86B85')
  for (let x = 104; x < 244; x += 12) out += R(x, 236, 4, 2, '#C9A45B')
