}

function floor(): string {
  let out = R(0, FLOOR_Y, W, 3, FLOOR)
  for (let x = 6; x < W; x += 28) out += R(x, 243, 14, 1.5, FLOOR, op(0.7))
  for (let x = 20; x < W; x += 40) out += R(x, 253, 10, 1.5, FLOOR, op(0.45))
