  else out += R(357, 193, 8, 1, '#6B3F27', op(0.5))
  out += R(355, 182, 2, 14, PAPER) + R(365, 182, 2, 14, PAPER) + R(355, 194, 12, 2, PAPER) +
    R(367, 185, 3, 2, PAPER) + R(369, 185, 2, 8, PAPER) + R(367, 191, 3, 2, PAPER) +
