    R(354, 182, 1, 14, DIM) + R(367, 182, 1, 3, DIM) + R(368, 184, 3, 1, DIM) + R(371, 184, 1, 10, DIM) +
    R(368, 193, 3, 1, DIM) + R(367, 193, 1, 3, DIM)
