function scrTest(): string {
  let out = R(0, 0, 64, 40, '#101412')
  const r = rand(53)
  for (let i = 0; i < 5; i++) {
    const y = 3 + i * 6.5
    const fail = i === 3
    const mark = fail
      ? pmap(['1...1', '.1.1.', '..1..', '.1.1.', '1...1'], 3, y, 1, { '1': '#E06C5A' })
      : pmap(['....1', '...1.', '1.1..', '.1...'], 3, y + 0.5, 1.2, { '1': TERM })
