// A firework burst: two rings of 8 sparks round a white core, popping out from the centre.
function burst(cx: number, cy: number, colors: readonly [string, string], d: number): string {
  let sparks = R(cx - 1, cy - 1, 2, 2, '#FFFFFF')
  for (let k = 0; k < 8; k++) {
