    sparks += R(Math.round(cx + Math.cos(a) * 5) - 1, Math.round(cy + Math.sin(a) * 5) - 1, 2, 2, colors[0]) +
      R(Math.round(cx + Math.cos(a + 0.4) * 9) - 1, Math.round(cy + Math.sin(a + 0.4) * 9) - 1, 2, 2, colors[1])
  }
  return `<g class="fw"${delay(d)}>${sparks}</g>`
}

